package ch.bbw.zork;import java.util.Arrays;/** * Class Command - Part of the "Zork" game. *  * author: Michael Kolling version: 1.0 date: July 1999 * refactoring: Rinaldo Lanza, September 2020 */public abstract class Command {	private String commandWord;	private String summary;	private String helpText;	private String exampleString;	private int time;    private String[] validArgs;    private int minArgs;    private int maxArgs;    public Command(String commandWord, int time) {        this.commandWord = commandWord;        this.time = time;        this.validArgs = new String[0];        this.minArgs = 0;        this.maxArgs = 0;        this.exampleString = "";        this.helpText = "";        this.summary = "";    }	public String getCommandWord() {		return commandWord;	}	public String getSummary() {return summary; }	public int getTime() { return time; }	public String getExampleString() { return exampleString; }	public void setSummary(String summary) {		this.summary = summary;	}	public void setHelpText(String helpText) {		this.helpText = helpText;	}	public void setExampleString(String exampleString) {		this.exampleString = exampleString;	}    public void setMaxArgs(int maxArgs) {        this.maxArgs = maxArgs;    }    public void setMinArgs(int minArgs) {        this.minArgs = minArgs;    }    public void setValidArgs(String... validArgs) {        this.validArgs = validArgs;    }    public int getMaxArgs() {        return maxArgs;    }    public int getMinArgs() {        return minArgs;    }    public String[] getValidArgs() {        return validArgs;    }    public String getHelpText() {        return helpText;    }    public boolean checkArgValidity(String... args) {        if (args.length < minArgs || args.length > maxArgs) {            return false;        }        for (String arg : args) {            if (!Arrays.asList(validArgs).contains(arg)) {                return false;            }        }        return true;    }	@Override	public String toString() {		String result = String.join("\n",				helpText,				"Time loss:\t" + time + " min"		);		if (!exampleString.isEmpty()) {			result = String.join("\n", result, "Example:\t" + exampleString);		}		return String.format("%s%n", result);	}}